 IF EXISTS(SELECT 1 FROM jsonb_array_elements(expected) e LEFT JOIN pg_proc p ON p.oid=to_regprocedure(e->>'signature') WHERE p.oid IS NULL OR encode(sha256(convert_to(p.prosrc,'UTF8')),'hex') IS DISTINCT FROM e->>'bodySha256' OR pg_get_userbyid(p.proowner) IS DISTINCT FROM e->>'owner' OR to_jsonb(p.proconfig) IS DISTINCT FROM e->'configuration' OR p.prosecdef IS DISTINCT FROM (e->>'securityDefiner')::boolean OR p.provolatile::text IS DISTINCT FROM e->>'volatility' OR (SELECT coalesce(jsonb_agg(jsonb_build_object('grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,'grantor',pg_get_userbyid(x.grantor),'privilege',x.privilege_type,'grantable',x.is_grantable)ORDER BY x.grantee,x.privilege_type),'[]'::jsonb)FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner)))x) IS DISTINCT FROM e->'acl') THEN RAISE EXCEPTION 'DRIVING_REVOKE_CURRENT_FUNCTION_OR_ACL_DRIFT'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid='public.account_deletion_subject_write_guard()'::regprocedure AND p.proowner='postgres'::regrole AND p.prosecdef AND encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')='82a48095b102fb498d2bcbb223d21440a190d3216a1b999d790257bba46adfd7') THEN RAISE EXCEPTION 'DRIVING_REVOKE_ACCOUNT_FENCE_BODY_DRIFT'; END IF;
 IF NOT EXISTS (SELECT 1 FROM pg_trigger t WHERE t.tgrelid='public.org_staff'::regclass
  AND t.tgname='account_deletion_subject_fence' AND t.tgenabled='O' AND t.tgtype=23
  AND t.tgfoid='public.account_deletion_subject_write_guard()'::regprocedure
  AND encode(t.tgargs,'escape')='user_id\000')
 OR NOT EXISTS (SELECT 1 FROM pg_trigger t WHERE t.tgrelid='public.user_roles'::regclass
  AND t.tgname='account_deletion_subject_fence' AND t.tgenabled='O' AND t.tgtype=23
  AND t.tgfoid='public.account_deletion_subject_write_guard()'::regprocedure
  AND encode(t.tgargs,'escape')='user_id\000') THEN
  RAISE EXCEPTION 'DRIVING_REVOKE_SUBJECT_FENCE_DRIFT';
 END IF;
END $preflight$;

CREATE TABLE public.driving_membership_revocations (
 request_id uuid PRIMARY KEY,
 membership_id uuid NOT NULL UNIQUE,
 organization_id uuid NOT NULL,
 user_id uuid NOT NULL,
 role public.driving_member_role NOT NULL,
 target_id uuid NOT NULL,
 actor_id uuid NOT NULL,
 reason text NOT NULL CHECK (length(btrim(reason)) BETWEEN 1 AND 2000),
 expected_updated_at timestamptz NOT NULL,
 member_snapshot jsonb NOT NULL CHECK (jsonb_typeof(member_snapshot)='object'),
 request_sha256 text NOT NULL CHECK (request_sha256 ~ '^[0-9a-f]{64}$'),
 receipt jsonb NOT NULL CHECK (jsonb_typeof(receipt)='object'),
 revoked_at timestamptz NOT NULL,
 CHECK (user_id <> actor_id)
);
COMMENT ON TABLE public.driving_membership_revocations IS
 'Append-only school-only exact-grant revocations. Historical tuples survive legitimate later grant/resource deletion. No automatic expiry/restore policy.';
ALTER TABLE public.driving_membership_revocations ENABLE ROW LEVEL SECURITY;

CREATE FUNCTION public.driving_membership_revocation_immutable()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $function$
BEGIN
 RAISE EXCEPTION 'DRIVING_MEMBERSHIP_REVOCATION_IMMUTABLE' USING ERRCODE='42501';
END $function$;
CREATE TRIGGER driving_membership_revocations_immutable_row
 BEFORE UPDATE OR DELETE ON public.driving_membership_revocations
 FOR EACH ROW EXECUTE FUNCTION public.driving_membership_revocation_immutable();
CREATE TRIGGER driving_membership_revocations_immutable_truncate
 BEFORE TRUNCATE ON public.driving_membership_revocations
 FOR EACH STATEMENT EXECUTE FUNCTION public.driving_membership_revocation_immutable();

CREATE FUNCTION public.driving_get_resource_access(_organization_id uuid,_role text,_target_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path=pg_catalog,public SET lock_timeout='3s' AS $function$
DECLARE
 v_actor uuid:=auth.uid(); v_user uuid; v_member public.driving_memberships;
 v_revoke public.driving_membership_revocations; v_state text; v_member_json jsonb;
BEGIN
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN
  RAISE EXCEPTION 'DRIVING_READ_COMMITTED_REQUIRED' USING ERRCODE='25000'; END IF;
 IF auth.role() IS DISTINCT FROM 'authenticated' OR v_actor IS NULL OR _organization_id IS NULL THEN
  RAISE EXCEPTION 'DRIVING_FORBIDDEN: требуется исходный аккаунт владельца школы' USING ERRCODE='42501'; END IF;
 IF _role IS NULL OR _role NOT IN ('student','instructor') OR _target_id IS NULL THEN
  RAISE EXCEPTION 'DRIVING_INVALID: выберите ученика или инструктора' USING ERRCODE='22023'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('driving:'||_organization_id::text,0)) THEN
  RAISE EXCEPTION 'DRIVING_CONFLICT: обновите данные школы' USING ERRCODE='40001'; END IF;
 PERFORM public.driving_assert_manage(_organization_id);
 -- Hold existing positive caller authority through this statement, including
 -- DELETE paths that do not participate in the account INSERT/UPDATE fence.
 -- No missing-profile denial is added: the existing admin fallback stays intact.
 PERFORM 1 FROM public.user_roles ur WHERE ur.user_id=v_actor FOR SHARE NOWAIT;
 PERFORM 1 FROM public.profiles p WHERE p.user_id=v_actor FOR SHARE NOWAIT;
 PERFORM 1 FROM public.org_staff os WHERE os.organization_id=_organization_id AND os.user_id=v_actor FOR SHARE NOWAIT;
 PERFORM public.driving_assert_manage(_organization_id);
 IF NOT EXISTS(SELECT 1 FROM public.driving_schools WHERE organization_id=_organization_id) THEN
  RAISE EXCEPTION 'DRIVING_NOT_FOUND: школа не подключена' USING ERRCODE='P0002'; END IF;
 IF _role='student' THEN
  SELECT user_id INTO v_user FROM public.driving_students
   WHERE organization_id=_organization_id AND id=_target_id FOR SHARE NOWAIT;
 ELSE
  SELECT user_id INTO v_user FROM public.driving_instructors
   WHERE organization_id=_organization_id AND id=_target_id FOR SHARE NOWAIT;
 END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'DRIVING_NOT_FOUND: запись не найдена' USING ERRCODE='P0002'; END IF;
 SELECT * INTO v_member FROM public.driving_memberships m WHERE m.organization_id=_organization_id
  AND m.role=_role::public.driving_member_role
  AND CASE WHEN _role='student' THEN m.student_id ELSE m.instructor_id END=_target_id FOR SHARE NOWAIT;
 IF NOT FOUND THEN v_state:='unlinked';
 ELSIF v_user IS DISTINCT FROM v_member.user_id THEN
  RAISE EXCEPTION 'DRIVING_CONFLICT: привязка аккаунта изменилась' USING ERRCODE='40001';
 ELSIF v_member.user_id=v_actor OR EXISTS(SELECT 1 FROM public.user_roles ur
   WHERE ur.user_id=v_member.user_id AND ur.role IN ('admin'::public.app_role,'organization'::public.app_role))
  OR EXISTS(SELECT 1 FROM public.org_staff os WHERE os.organization_id=_organization_id
   AND os.user_id=v_member.user_id AND (os.expires_at IS NULL OR os.expires_at>now())) THEN
  v_state:='protected';
 ELSE
  SELECT * INTO v_revoke FROM public.driving_membership_revocations WHERE membership_id=v_member.id;
  v_state:=CASE WHEN FOUND THEN 'revoked' ELSE 'linked' END;
  v_member_json:=jsonb_build_object('id',v_member.id,'user_id',v_member.user_id,'updated_at',v_member.updated_at);
 END IF;
 RETURN jsonb_build_object('contract_version','driving_membership_access_v1','actor_id',v_actor,
  'organization_id',_organization_id,'role',_role,'target_id',_target_id,'state',v_state,
  'membership',v_member_json,'revocation',CASE WHEN v_state='revoked' THEN
   jsonb_build_object('request_id',v_revoke.request_id,'revoked_at',v_revoke.revoked_at) ELSE NULL END);
EXCEPTION WHEN lock_not_available THEN
 RAISE EXCEPTION 'DRIVING_CONFLICT: обновите данные школы' USING ERRCODE='40001';
END $function$;

CREATE FUNCTION public.driving_revoke_membership(
 _organization_id uuid,_membership_id uuid,_expected_user_id uuid,_role text,_target_id uuid,
 _expected_updated_at timestamptz,_request_id uuid,_reason text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path=pg_catalog,public SET lock_timeout='3s' AS $function$
DECLARE
 v_actor uuid:=auth.uid(); v_subject uuid; v_user uuid; v_member public.driving_memberships;
 v_existing public.driving_membership_revocations; v_hash text; v_receipt jsonb; v_at timestamptz;
BEGIN
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN
  RAISE EXCEPTION 'DRIVING_READ_COMMITTED_REQUIRED' USING ERRCODE='25000'; END IF;
 IF auth.role() IS DISTINCT FROM 'authenticated' OR v_actor IS NULL OR _organization_id IS NULL THEN
  RAISE EXCEPTION 'DRIVING_FORBIDDEN: требуется исходный аккаунт владельца школы' USING ERRCODE='42501'; END IF;
 IF _membership_id IS NULL OR _expected_user_id IS NULL OR _target_id IS NULL OR _expected_updated_at IS NULL
  OR _request_id IS NULL OR _role IS NULL OR _role NOT IN ('student','instructor')
  OR _reason IS NULL OR length(btrim(_reason)) NOT BETWEEN 1 AND 2000 THEN
  RAISE EXCEPTION 'DRIVING_INVALID: подтвердите участника и причину отзыва' USING ERRCODE='22023'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('driving:'||_organization_id::text,0)) THEN
  RAISE EXCEPTION 'DRIVING_CONFLICT: обновите данные школы' USING ERRCODE='40001'; END IF;
 -- Same school writer fence as existing grant/invite/link operations. Subject
 -- TRY fences serialize membership reads/account and role writers without waits.
 PERFORM public.driving_assert_manage(_organization_id);
 FOR v_subject IN SELECT DISTINCT x FROM unnest(ARRAY[v_actor,_expected_user_id]) x ORDER BY x LOOP
  IF NOT pg_try_advisory_xact_lock(hashtextextended(v_subject::text,42007)) THEN
   RAISE EXCEPTION 'DRIVING_ACCOUNT_CONFLICT: повторите проверку доступа' USING ERRCODE='40001'; END IF;
 END LOOP;
 -- Hold existing positive caller authority through this statement, including
 -- DELETE paths that do not participate in the account INSERT/UPDATE fence.
 -- No missing-profile denial is added: the existing admin fallback stays intact.
 PERFORM 1 FROM public.user_roles ur WHERE ur.user_id=v_actor FOR SHARE NOWAIT;
 PERFORM 1 FROM public.profiles p WHERE p.user_id=v_actor FOR SHARE NOWAIT;
 PERFORM 1 FROM public.org_staff os WHERE os.organization_id=_organization_id AND os.user_id=v_actor FOR SHARE NOWAIT;
 PERFORM public.driving_assert_manage(_organization_id);
 IF NOT EXISTS(SELECT 1 FROM public.driving_schools WHERE organization_id=_organization_id) THEN
  RAISE EXCEPTION 'DRIVING_NOT_FOUND: школа не подключена' USING ERRCODE='P0002'; END IF;
 v_hash:=encode(sha256(convert_to(jsonb_build_object('actor',v_actor,'org',_organization_id,
  'membership',_membership_id,'user',_expected_user_id,'role',_role,'target',_target_id,
  'version_epoch',extract(epoch from _expected_updated_at),'reason',btrim(_reason))::text,'UTF8')),'hex');
 SELECT * INTO v_existing FROM public.driving_membership_revocations WHERE request_id=_request_id;
 IF FOUND THEN
  IF v_existing.actor_id IS DISTINCT FROM v_actor OR v_existing.organization_id IS DISTINCT FROM _organization_id
   OR v_existing.request_sha256 IS DISTINCT FROM v_hash THEN
   RAISE EXCEPTION 'DRIVING_CONFLICT: запрос не соответствует подтверждённому отзыву' USING ERRCODE='40001'; END IF;
  RETURN v_existing.receipt;
 END IF;
 IF _role='student' THEN
  SELECT user_id INTO v_user FROM public.driving_students
   WHERE organization_id=_organization_id AND id=_target_id FOR SHARE NOWAIT;
 ELSE
  SELECT user_id INTO v_user FROM public.driving_instructors
   WHERE organization_id=_organization_id AND id=_target_id FOR SHARE NOWAIT;
 END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'DRIVING_NOT_FOUND: запись не найдена' USING ERRCODE='P0002'; END IF;
 SELECT * INTO v_member FROM public.driving_memberships m WHERE m.organization_id=_organization_id
  AND m.id=_membership_id AND m.user_id=_expected_user_id AND m.role=_role::public.driving_member_role
  AND CASE WHEN _role='student' THEN m.student_id ELSE m.instructor_id END=_target_id FOR SHARE NOWAIT;
 IF NOT FOUND OR v_user IS DISTINCT FROM v_member.user_id OR v_member.updated_at IS DISTINCT FROM _expected_updated_at THEN
  RAISE EXCEPTION 'DRIVING_CONFLICT: привязка участника изменилась, обновите данные' USING ERRCODE='40001'; END IF;
 IF v_member.user_id=v_actor OR EXISTS(SELECT 1 FROM public.user_roles ur
   WHERE ur.user_id=v_member.user_id AND ur.role IN ('admin'::public.app_role,'organization'::public.app_role))
  OR EXISTS(SELECT 1 FROM public.org_staff os WHERE os.organization_id=_organization_id
   AND os.user_id=v_member.user_id AND (os.expires_at IS NULL OR os.expires_at>now())) THEN
  RAISE EXCEPTION 'DRIVING_FORBIDDEN: управленческий доступ здесь не отзывается' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM public.driving_membership_revocations WHERE membership_id=v_member.id) THEN
  RAISE EXCEPTION 'DRIVING_CONFLICT: доступ уже отозван, обновите данные' USING ERRCODE='40001'; END IF;
 v_at:=clock_timestamp();
 v_receipt:=jsonb_build_object('contract_version','driving_membership_revocation_v1','actor_id',v_actor,
  'organization_id',_organization_id,'membership_id',v_member.id,'user_id',v_member.user_id,
  'role',_role,'target_id',_target_id,'request_id',_request_id,'revoked_at',v_at);
 INSERT INTO public.driving_membership_revocations(request_id,membership_id,organization_id,user_id,role,
  target_id,actor_id,reason,expected_updated_at,member_snapshot,request_sha256,receipt,revoked_at)
 VALUES(_request_id,v_member.id,_organization_id,v_member.user_id,v_member.role,_target_id,v_actor,
  btrim(_reason),_expected_updated_at,to_jsonb(v_member),v_hash,v_receipt,v_at);
 PERFORM public.driving_log(_organization_id,'revoke_membership',_target_id::text,
  jsonb_build_object('membership_id',v_member.id,'role',_role,'request_id',_request_id,'reason',btrim(_reason)));
 RETURN v_receipt;
EXCEPTION WHEN lock_not_available THEN
 RAISE EXCEPTION 'DRIVING_CONFLICT: обновите данные школы' USING ERRCODE='40001';
END $function$;

CREATE OR REPLACE FUNCTION public.driving_membership(_organization_id uuid)
 RETURNS TABLE(role driving_member_role, student_id uuid, instructor_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE actor uuid:=auth.uid();BEGIN
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN
  RAISE EXCEPTION 'DRIVING_READ_COMMITTED_REQUIRED' USING ERRCODE='25000';
 END IF;
 IF auth.role()IS DISTINCT FROM'authenticated'OR actor IS NULL OR _organization_id IS NULL THEN RETURN;END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended(actor::text,42007))THEN
  RAISE EXCEPTION 'DRIVING_ACCOUNT_CONFLICT: повторите проверку доступа' USING ERRCODE='40001';END IF;
 IF EXISTS(SELECT 1 FROM public.account_deletion_revocations WHERE user_id=actor)THEN RETURN;END IF;
 RETURN QUERY SELECT m.role,m.student_id,m.instructor_id FROM public.driving_memberships m
 JOIN public.profiles p ON p.user_id=m.user_id AND p.organization_id=m.organization_id
  AND p.blocked_at IS NULL AND p.archived_at IS NULL
 JOIN auth.users u ON u.id=m.user_id AND u.email_confirmed_at IS NOT NULL
 WHERE m.user_id=auth.uid()AND m.organization_id=_organization_id
 AND NOT EXISTS(SELECT 1 FROM public.driving_membership_revocations revoked WHERE revoked.membership_id=m.id) AND(
  (m.role='student'AND EXISTS(SELECT 1 FROM public.driving_students s WHERE s.organization_id=m.organization_id
   AND s.id=m.student_id AND s.user_id=m.user_id AND s.active))
  OR(m.role='instructor'AND EXISTS(SELECT 1 FROM public.driving_instructors i WHERE i.organization_id=m.organization_id
   AND i.id=m.instructor_id AND i.user_id=m.user_id AND i.active)))
 ORDER BY CASE m.role WHEN'instructor'THEN 0 ELSE 1 END LIMIT 1;
END;$function$
;
DO $new_acl$
DECLARE object_oid oid; owner_oid oid; acl_role oid; function_signature text; role_sql text;
BEGIN
 SELECT c.oid,c.relowner INTO object_oid,owner_oid FROM pg_class c WHERE c.oid='public.driving_membership_revocations'::regclass;
 FOR acl_role IN SELECT DISTINCT x.grantee FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) x WHERE c.oid=object_oid AND x.grantee<>owner_oid LOOP
  role_sql:=CASE WHEN acl_role=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(acl_role)) END;
  EXECUTE 'REVOKE ALL ON TABLE public.driving_membership_revocations FROM '||role_sql;
 END LOOP;
 FOREACH function_signature IN ARRAY ARRAY['public.driving_membership_revocation_immutable()','public.driving_get_resource_access(uuid,text,uuid)','public.driving_revoke_membership(uuid,uuid,uuid,text,uuid,timestamp with time zone,uuid,text)'] LOOP
  SELECT p.oid,p.proowner INTO object_oid,owner_oid FROM pg_proc p WHERE p.oid=to_regprocedure(function_signature);
  FOR acl_role IN SELECT DISTINCT x.grantee FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x WHERE p.oid=object_oid AND x.grantee<>owner_oid LOOP
   role_sql:=CASE WHEN acl_role=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(acl_role)) END;
   EXECUTE 'REVOKE ALL ON FUNCTION '||function_signature||' FROM '||role_sql;
  END LOOP;
 END LOOP;
END $new_acl$;
